/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, accessSync } from 'node:fs';
import { importStock } from './src/entry.js';

const answer = JSON.parse(readFileSync('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), ['files', 'output', 'invalid_numeric', 'reserved_applied_before_clamp']);
assert.deepEqual(answer.files, ['src/entry.js', 'src/input/csv.js', 'src/domain/stock.js', 'src/domain/sku.js', 'src/output/wire.js']);
answer.files.forEach(path => accessSync(path));
assert.deepEqual(answer.output, importStock(' ab-2 ,5,8'));
assert.throws(() => importStock('x,no,1'), error => error.message === answer.invalid_numeric);
assert.equal(answer.reserved_applied_before_clamp, true);
assert.deepEqual(importStock('x,-1,-2'), { product_code: 'X', units: 1, schema: 2 });
assert.deepEqual(importStock('x,-1,0'), { product_code: 'X', units: 0, schema: 2 });
console.log('answer.json and importStock checks passed');
NODE"

